617	    private String splitBody(String commandKey, List<String[]> children) {
618	        StringBuilder sb = new StringBuilder("{\"commandKey\":\"").append(commandKey)
619	                .append("\",\"children\":[");
620	        for (int i = 0; i < children.size(); i++) {
621	            if (i > 0) {
622	                sb.append(',');
623	            }
624	            sb.append("{\"batchKey\":\"").append(children.get(i)[0])
625	                    .append("\",\"batchNo\":\"").append(children.get(i)[1]).append("\"}");
626	        }
627	        return sb.append("]}").toString();
