public StoredResponse create(CreateHandoffRequest req) {
    String source = req.sourcePlant().trim();
    String target = req.targetPlant().trim();
    if (source.equals(target)) throw unprocessable("目标厂不能与源厂相同");
    // dedupe check
    List<CreateHandoffRequest.Item> items = req.items();
    List<String> keys = items.stream().map(Item::batchKey).toList();
    if (new HashSet<>(keys).size() != keys.size()) throw conflict("清单内 batchKey 重复");
    // sort by batchKey for freeze + fingerprint (order-insensitive)
    List<Item> sorted = items.stream().sorted(comparing(Item::batchKey)).toList();
    String fingerprint = fingerprint over sorted (batchKey, expectedVersion) + plants + manifestKey + expectedArrivalAt.
    return batchService.executeIdempotent(CMD_CREATE, req.requestId(), fingerprint, () -> {
        // manifestKey uniqueness pre-check
        repo.findHandoff(req.manifestKey()).ifPresent(h -> { throw conflict("manifestKey 已存在"); });
        // lock batches sorted
        Map<String, BatchRow> batches = new HashMap<>();
        for (Item item : sorted) {
            BatchRow b = repo.findBatchForUpdate(item.batchKey()).orElseThrow(notFound);
            batches.put(...);
        }
        // active handoff membership
        List<String> inHandoff = repo.findBatchesInActiveHandoff(keys);
        if (!inHandoff.isEmpty()) throw conflict("批次已在其他移交中: " + ...);
        Map<String,String> parentOf = batchService.childToParent();
        Set<String> recalled = new HashSet<>(repo.findRecalledKeys());
        for (Item item : sorted) {
            BatchRow b = batches.get(item.batchKey());
            if (!b.holdingPlant().equals(source)) throw conflict("批次当前不由源厂持有");
            if (RELEASED.equals(b.status())) throw conflict("RELEASED 批次不可移交");
            if (b.batchVersion() != item.expectedVersion()) throw conflict("expectedVersion 与当前版本不一致");
            if (RECALLED.equals(b.status()) || recalledAncestor present) throw unprocessable("存在有效召回");
        }
        String now = batchService.now();
        repo.insertHandoff(new HandoffRow(0L, manifestKey, source, target, expectedArrivalAt.toString(), CREATED, null, now, null, null, null));
        int seq = 1;
        List<HandoffItemResponse> itemViews = ...;
        for (Item item : sorted) {
            List<AncestorSnapshot> lineage = ancestorSnapshot(item.batchKey(), parentOf, recalled);
            repo.insertHandoffItem(new HandoffItemRow(0L, manifestKey, item.batchKey(), seq, item.expectedVersion(), batchService.toJson(lineage), null, null, null));
            itemViews.add(new HandoffItemResponse(seq, batchKey, expectedVersion, null, null, null, lineage));
            seq++;
        }
        HandoffResponse body = new HandoffResponse(manifestKey, source, target, CREATED, expectedArrivalAt, null, Instant.parse(now), null, null, null, itemViews);
        return new StoredResponse(201, batchService.toJson(body));
    });
}
