            if (!seal.equals(item.sealNo())) throw unprocessable("封签不符: " + key);
            if (recalled.contains(key) || recalledAncestor(...).isPresent()) throw unprocessable("运输中新增召回，拒绝接收: " + key);
        }
        String now = now();
        for (item : items) {
            repo.updateBatchReceived(key, QUARANTINED, handoff.targetPlant(), item.expectedVersion() + 1);
            repo.updateItemReceived(manifestKey, key, item.expectedVersion() + 1);
        }
        repo.updateHandoffReceived(manifestKey, receiver, now);
        return new StoredResponse(200, toJson(toResponse(manifestKey)));
    });
}
