private Map<String, String> validateSealCoverage(List<SealSpec> specs, List<HandoffItemRow> items, String phase) {
    Set<String> seen = new HashSet<>();
    Map<String, String> sealByBatch = new HashMap<>();
    for (SealSpec spec : specs) {
        if (!seen.add(spec.batchKey())) throw unprocessable(phase + "清单重复批次: " + spec.batchKey());
        sealByBatch.put(spec.batchKey(), spec.sealNo());
    }
    Set<String> manifest = items.stream().map(HandoffItemRow::batchKey).collect(toSet());
    for (String key : manifest) if (!sealByBatch.containsKey(key)) throw unprocessable(phase + "清单遗漏批次: " + key);
    for (String key : sealByBatch.keySet()) if (!manifest.contains(key)) throw unprocessable(phase + "清单包含多余批次: " + key);
    return sealByBatch;
}
