        // 重复批次
        ship(manifest, "RID-SC-3", PLANT_A,
                List.of(seal(b1, "S1"), seal(b1, "S1")), 422);
        // 非源厂发运
        ship(manifest, "RID-SC-4", PLANT_B, List.of(seal(b1, "S1"), seal(b2, "S2")), 409);

        // 全部失败不产生任何部分发运
        assertEquals("QUARANTINED", currentStatus(b1));
