    receive(manifest, "RID-AH-R", PLANT_B, "recv", List.of(seal(b1, "S1")), 200);
    createHandoff("RID-AH4", "MF-AH4-" + unique(), PLANT_A, PLANT_B,
            List.of(item(b1, 0)), 409);
